import os, shutil, re

base = os.getcwd()
gelen = os.path.join(base, 'gelen')
arsiv = os.path.join(base, 'arsiv')
media_ext = {'.jpg', '.jpeg', '.png', '.mp4', '.mov'}
pat8 = re.compile(r'(20\d{6})')
pat10 = re.compile(r'(\d{4}-\d{2}-\d{2})')

if not os.path.exists(gelen):
    print(f'Gelen klasörü bulunamadı: {gelen}')
else:
    os.makedirs(arsiv, exist_ok=True)
    moved = 0
    skipped = 0

    for root, dirs, files in os.walk(gelen):
        for f in files:
            _, ext = os.path.splitext(f)
            if ext.lower() not in media_ext:
                skipped += 1
                continue

            full_path = os.path.join(root, f)
            m8 = pat8.search(f)
            m10 = pat10.search(f)

            pos8 = m8.start() if m8 else 999
            pos10 = m10.start() if m10 else 999

            if pos8 < pos10:
                chosen = m8
            else:
                chosen = m10

            if chosen:
                ds = chosen.group(1)
                y = ds[:4]
                m = ds[4:8] if len(ds) == 8 else ds[5:7]
            else:
                y = 'tarihsiz'
                m = ''

            if y != 'tarihsiz':
                target_dir = os.path.join(arsiv, y, m)
            else:
                target_dir = os.path.join(arsiv, 'tarihsiz')

            os.makedirs(target_dir, exist_ok=True)
            try:
                shutil.move(full_path, os.path.join(target_dir, f))
                moved += 1
            except Exception as e:
                print(f'Hata {f}: {e}')

    print(f'\nIslem tamam. Tasandi: {moved}, Atlandi (medya degil): {skipped}')
